// n8n Code node — Detect Price Changes
// Runs in the Weekly Analysis workflow after n8n_aggregate_snapshots.js.
//
// Input:  one item from Aggregate Snapshots node (products array with 7-day history)
// Output: array of change records — one item per detected change across all products
//         Returns empty array if no changes detected (triggers IF node downstream).

const { products } = $input.first().json;
const now = new Date().toISOString();
const changes = [];

for (const p of products) {
  if (!p.product_id) continue;

  const base = {
    timestamp: now,
    product_id: p.product_id,
    competitor_name: p.competitor_name,
    vitamin: p.vitamin,
    product_name: p.product_name,
    normalization_quality: p.normalization_quality,
  };

  // Price change — threshold 0.1% to filter floating-point noise
  if (p.price_latest !== null && p.price_baseline !== null && p.price_delta_pct !== null) {
    if (Math.abs(p.price_delta_pct) >= 0.1) {
      changes.push({
        ...base,
        change_type: 'price_change',
        value_before: Number(p.price_baseline).toFixed(2),
        value_after: Number(p.price_latest).toFixed(2),
        pct_delta: p.price_delta_pct,
      });
    }
  }

  // Cost-per-serving change — verified quality only, threshold 0.1%
  if (
    p.cps_latest !== null &&
    p.cps_baseline !== null &&
    p.cps_delta_pct !== null &&
    p.normalization_quality === 'verified'
  ) {
    if (Math.abs(p.cps_delta_pct) >= 0.1) {
      changes.push({
        ...base,
        change_type: 'cost_per_serving_change',
        value_before: Number(p.cps_baseline).toFixed(4),
        value_after: Number(p.cps_latest).toFixed(4),
        pct_delta: p.cps_delta_pct,
      });
    }
  }

  // Availability change — compare oldest vs latest snapshot in the 7-day window
  const snapDates = Object.keys(p.snapshots_by_day || {}).sort();
  if (snapDates.length >= 2) {
    const firstAvail = p.snapshots_by_day[snapDates[0]].availability;
    const lastAvail = p.snapshots_by_day[snapDates[snapDates.length - 1]].availability;
    if (firstAvail && lastAvail && firstAvail !== lastAvail) {
      changes.push({
        ...base,
        change_type: 'availability_change',
        value_before: firstAvail,
        value_after: lastAvail,
        pct_delta: null,
      });
    }
  }
}

// Return one item per change; or a single no-changes sentinel so the IF node works
if (changes.length === 0) {
  return [{ json: { no_changes: true } }];
}

return changes.map(c => ({ json: c }));

// n8n Code node — Aggregate Snapshots for Weekly Analysis
// Runs in the Weekly Analysis workflow after reading the products sheet
// and the last-7-days slice of the snapshots sheet.
//
// Input (from two preceding nodes, accessed via node name):
//   $('Read Products Sheet').all()   — product registry
//   $('Read Snapshots').all()        — snapshot rows (last 7 days)
//
// Output: one item containing:
//   products         — enriched product list with 7-day history attached
//   summary_table_md — markdown table for Claude prompt
//   run_stats        — counts for the analysis tab

const products = $('Read Products Sheet').all().map(i => i.json);
const snapshots = $('Read Snapshots').all().map(i => i.json);

// Index snapshots by product_id → sorted array of {run_date, price, cost_per_serving, availability}
const snapshotsByProduct = {};
for (const snap of snapshots) {
  const pid = snap.product_id;
  if (!pid) continue;
  if (!snapshotsByProduct[pid]) snapshotsByProduct[pid] = [];
  snapshotsByProduct[pid].push({
    run_date: snap.run_date,
    price: snap.price != null ? parseFloat(snap.price) : null,
    cost_per_serving: snap.cost_per_serving != null ? parseFloat(snap.cost_per_serving) : null,
    availability: snap.availability || "unknown",
    normalization_quality: snap.normalization_quality || "unresolvable",
  });
}

// Sort each product's snapshots chronologically
for (const pid of Object.keys(snapshotsByProduct)) {
  snapshotsByProduct[pid].sort((a, b) => a.run_date.localeCompare(b.run_date));
}

// Enrich products with their snapshot history and computed deltas
const enrichedProducts = [];
for (const product of products) {
  const pid = product.product_id;
  if (!pid) continue;

  const history = snapshotsByProduct[pid] || [];
  const latest = history[history.length - 1] || null;
  const baseline = history[0] || null;  // oldest in 7-day window = comparison point

  let priceLatest = latest?.price ?? null;
  let priceBaseline = baseline?.price ?? null;
  let priceDeltaPct = null;
  if (priceLatest !== null && priceBaseline !== null && priceBaseline > 0) {
    priceDeltaPct = parseFloat(((priceLatest - priceBaseline) / priceBaseline * 100).toFixed(2));
  }

  let cpsLatest = latest?.cost_per_serving ?? null;
  let cpsBaseline = baseline?.cost_per_serving ?? null;
  let cpsDeltaPct = null;
  if (cpsLatest !== null && cpsBaseline !== null && cpsBaseline > 0) {
    cpsDeltaPct = parseFloat(((cpsLatest - cpsBaseline) / cpsBaseline * 100).toFixed(2));
  }

  // Build snapshots_by_day map for the table
  const snapshotsByDay = {};
  for (const snap of history) {
    snapshotsByDay[snap.run_date] = snap;
  }

  enrichedProducts.push({
    product_id: pid,
    competitor_name: product.competitor_name,
    vitamin: product.vitamin,
    vitamin_code: product.vitamin_code,
    product_name: product.product_name,
    normalization_quality: product.normalization_quality,
    snapshots_by_day: snapshotsByDay,
    days_with_data: history.length,
    price_latest: priceLatest,
    price_baseline: priceBaseline,
    price_delta_pct: priceDeltaPct,
    cps_latest: cpsLatest,
    cps_baseline: cpsBaseline,
    cps_delta_pct: cpsDeltaPct,
    latest_availability: latest?.availability ?? "unknown",
    latest_date: latest?.run_date ?? null,
  });
}

// Collect all unique run dates in the window (for table columns)
const allDates = [...new Set(snapshots.map(s => s.run_date))].sort();
const dateHeaders = allDates.map(d => d.slice(5));  // MM-DD for column headers

// Build markdown summary table (cost_per_serving, formatted as $X.XXXX)
const headerRow = `| Product | ${dateHeaders.join(' | ')} | Δ% |`;
const separatorRow = `|---|${'---|'.repeat(dateHeaders.length + 1)}`;
const dataRows = enrichedProducts.map(p => {
  const cells = allDates.map(d => {
    const snap = p.snapshots_by_day[d];
    if (!snap || snap.cost_per_serving === null) return '—';
    return '$' + snap.cost_per_serving.toFixed(4);
  });
  const deltaStr = p.cps_delta_pct !== null
    ? (p.cps_delta_pct >= 0 ? '+' : '') + p.cps_delta_pct + '%'
    : '—';
  const label = `${p.competitor_name} ${p.vitamin_code}`;
  return `| ${label} | ${cells.join(' | ')} | ${deltaStr} |`;
});

const summaryTableMd = [headerRow, separatorRow, ...dataRows].join('\n');

// Run stats
const totalProducts = enrichedProducts.length;
const productsWithData = enrichedProducts.filter(p => p.days_with_data > 0).length;
const productsWithChange = enrichedProducts.filter(
  p => p.price_delta_pct !== null && Math.abs(p.price_delta_pct) >= 0.1
).length;

return [{
  json: {
    products: enrichedProducts,
    summary_table_md: summaryTableMd,
    all_dates: allDates,
    run_stats: {
      total_products: totalProducts,
      products_with_data: productsWithData,
      products_with_change: productsWithChange,
      date_range_start: allDates[0] || null,
      date_range_end: allDates[allDates.length - 1] || null,
    },
  }
}];

// Build Claude Input
// Gathers all change records from Detect Changes + aggregated data from Aggregate Snapshots
// Outputs a single item with prompt_text ready for the LLM Chain

const allChanges = $input.all().map(i => i.json);
const agg = $('Aggregate Snapshots').first().json;

const products = agg.products || [];

// Build a cost-per-serving summary table (markdown)
const tableRows = products.map(p => {
  const price = p.price_latest != null ? `$${Number(p.price_latest).toFixed(2)}` : 'N/A';
  const cps = p.cps_latest != null ? `$${Number(p.cps_latest).toFixed(4)}` : 'N/A';
  const trend = p.price_delta_pct != null
    ? (p.price_delta_pct > 0 ? `▲ ${p.price_delta_pct.toFixed(1)}%` : `▼ ${Math.abs(p.price_delta_pct).toFixed(1)}%`)
    : '—';
  return `| ${p.competitor_name} | ${p.product_name || p.product_id} | ${price} | ${cps} | ${trend} |`;
});

const summaryTable = [
  '| Competitor | Product | Current Price | Cost/Serving | 7-Day Change |',
  '|---|---|---|---|---|',
  ...tableRows
].join('\n');

// Describe each detected change
const changeLines = allChanges
  .filter(c => !c.no_changes)
  .map(c => {
    if (c.change_type === 'price_change') {
      const dir = Number(c.value_after) < Number(c.value_before) ? 'DROP' : 'INCREASE';
      return `- [${dir}] ${c.competitor_name} — ${c.product_name || c.product_id}: $${c.value_before} → $${c.value_after} (${c.pct_delta > 0 ? '+' : ''}${Number(c.pct_delta).toFixed(1)}%)`;
    }
    if (c.change_type === 'cost_per_serving_change') {
      return `- [COST/SERVING] ${c.competitor_name} — ${c.product_name || c.product_id}: $${c.value_before} → $${c.value_after} per serving`;
    }
    if (c.change_type === 'availability_change') {
      return `- [AVAILABILITY] ${c.competitor_name} — ${c.product_name || c.product_id}: ${c.value_before} → ${c.value_after}`;
    }
    return `- [CHANGE] ${JSON.stringify(c)}`;
  }).join('\n');

const dateStart = agg.date_range_start || '(unknown)';
const dateEnd = agg.date_range_end || '(unknown)';
const totalProducts = products.length;

const prompt_text = `You are a competitive pricing analyst for a supplement brand that tracks competitor vitamin pricing.

Analysis period: ${dateStart} to ${dateEnd}
Products monitored: ${totalProducts}

## Detected Changes This Week
${changeLines || 'No changes detected.'}

## Full 7-Day Pricing Snapshot
${summaryTable}

Respond with a JSON object containing:
- executive_summary (2–3 sentence strategic overview)
- significant_changes (array of objects with product_id, change_type, value_before, value_after, pct_delta, strategic_note)
- market_positioning_insights (lowest_cpp_product, highest_cpp_product, analyst_commentary)
- recommended_actions (array of {priority, action})`;

return [{ json: { prompt_text, change_count: allChanges.filter(c => !c.no_changes).length } }];

// Parse Claude Response
// Input: LLM Chain output with .text containing JSON string
// Output: parsed analysis fields + original changes array

const raw = $input.first().json.text || $input.first().json.output || '';

// Strip markdown fences if present
const cleaned = raw.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();

let analysis;
try {
  analysis = JSON.parse(cleaned);
} catch (e) {
  return [{ json: { parse_error: true, raw_text: raw, error: e.message } }];
}

return [{
  json: {
    executive_summary: analysis.executive_summary || '',
    significant_changes: analysis.significant_changes || [],
    market_positioning_insights: analysis.market_positioning_insights || {},
    recommended_actions: analysis.recommended_actions || [],
    run_date: new Date().toISOString().slice(0, 10),
    change_count: (analysis.significant_changes || []).length,
  }
}];

const d = $input.first().json;

const changesHtml = (d.significant_changes || []).map(c => {
  const isPositive = String(c.change_type).includes('INCREASE') || String(c.change_type).includes('RESTORED');
  const arrow = isPositive ? '▲' : '▼';
  const color = isPositive ? '#c0392b' : '#27ae60';
  return `
    <tr>
      <td style="padding:10px 8px;border-bottom:1px solid #eee;">${c.product_id}</td>
      <td style="padding:10px 8px;border-bottom:1px solid #eee;">${c.change_type}</td>
      <td style="padding:10px 8px;border-bottom:1px solid #eee;">${c.value_before} → ${c.value_after}</td>
      <td style="padding:10px 8px;border-bottom:1px solid #eee;color:${color};font-weight:bold;">
        ${c.pct_delta != null ? arrow + ' ' + Math.abs(Number(c.pct_delta)).toFixed(1) + '%' : '—'}
      </td>
    </tr>`;
}).join('');

const actionsHtml = (d.recommended_actions || []).map(a => {
  const colors = { HIGH: '#e74c3c', MEDIUM: '#e67e22', LOW: '#7f8c8d' };
  const bg = colors[a.priority] || '#7f8c8d';
  return `<li style="margin-bottom:10px;">
    <span style="background:${bg};color:#fff;font-size:11px;font-weight:bold;padding:2px 7px;border-radius:3px;margin-right:8px;">${a.priority}</span>
    ${a.action}
  </li>`;
}).join('');

const insights = d.market_positioning_insights || {};
const insightsHtml = insights.analyst_commentary
  ? `<p style="background:#f8f9fa;border-left:4px solid #3498db;padding:12px 16px;margin:0;font-size:14px;line-height:1.6;">${insights.analyst_commentary}</p>`
  : '';

const html = `
<html><body style="font-family:Arial,sans-serif;max-width:680px;margin:auto;color:#333;font-size:14px;">

  <div style="background:#1a1a2e;color:#fff;padding:20px 24px;border-radius:6px 6px 0 0;">
    <h2 style="margin:0;font-size:20px;">📊 Vitamin D3 Competitor Pricing Digest</h2>
    <p style="margin:6px 0 0;opacity:0.75;font-size:13px;">Week of ${d.run_date} · ${d.change_count} change${d.change_count !== 1 ? 's' : ''} detected</p>
  </div>

  <div style="padding:20px 24px;background:#fff;border:1px solid #e0e0e0;border-top:none;">

    <h3 style="color:#1a1a2e;margin-top:0;">Executive Summary</h3>
    <p style="line-height:1.7;">${d.executive_summary}</p>

    <h3 style="color:#1a1a2e;">Detected Changes</h3>
    <table style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead>
        <tr style="background:#f0f0f5;text-align:left;">
          <th style="padding:10px 8px;">Product</th>
          <th style="padding:10px 8px;">Type</th>
          <th style="padding:10px 8px;">Before → After</th>
          <th style="padding:10px 8px;">Δ%</th>
        </tr>
      </thead>
      <tbody>${changesHtml}</tbody>
    </table>

    ${insightsHtml ? `<h3 style="color:#1a1a2e;margin-top:24px;">Market Positioning</h3>${insightsHtml}` : ''}

    <h3 style="color:#1a1a2e;margin-top:24px;">Recommended Actions</h3>
    <ul style="line-height:1.8;padding-left:20px;">${actionsHtml}</ul>

    <p style="font-size:11px;color:#aaa;margin-top:32px;border-top:1px solid #eee;padding-top:12px;">
      Vitamin Price Monitor · Auto-generated ${d.run_date}
    </p>
  </div>

</body></html>`;

return [{
  json: {
    subject: `Vitamin D3 Pricing Digest — ${d.run_date} (${d.change_count} change${d.change_count !== 1 ? 's' : ''})`,
    html_body: html,
  }
}];
